package com.hau.notification.infrastructure.persistence.repository;import com.hau.notification.domain.model.ScheduledStatus;import com.hau.notification.infrastructure.persistence.entity.ScheduledNotificationEntity;import jakarta.persistence.LockModeType;import org.springframework.data.domain.Pageable;import org.springframework.data.jpa.repository.*;import java.time.Instant;import java.util.*;public interface JpaScheduledNotificationRepository extends JpaRepository<ScheduledNotificationEntity,UUID>{@Lock(LockModeType.PESSIMISTIC_WRITE)List<ScheduledNotificationEntity> findByStatusAndScheduledAtLessThanEqualOrderByScheduledAt(ScheduledStatus s,Instant at,Pageable p);}
